Your expense tracker is below. Add an item with an amount and a category, and it totals the month and shows where the money goes. Entries may not be kept after you close this page, so note down your totals.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:16px;background:#fafafa;color:#222}
h2{margin:0 0 12px}
.card{background:#fff;border:1px solid #e3e3e3;border-radius:10px;padding:12px;margin-bottom:12px}
.row{display:flex;gap:8px;flex-wrap:wrap}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
input{flex:1;min-width:110px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#b00;padding:2px 8px}
.big{font-size:26px;font-weight:600}
.bar{height:10px;background:#2b6cb0;border-radius:5px}
.track{background:#eee;border-radius:5px;margin:3px 0 8px}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.muted{color:#777;font-size:12px}
.over{color:#b00}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
  <div class="muted">Total this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px;align-items:center">
    <span class="muted">Monthly budget (₹)</span>
    <input id="budget" type="number" placeholder="e.g. 50000">
  </div>
  <div id="left" class="muted" style="margin-top:6px"></div>
</div>
<div class="card">
  <div class="row">
    <input id="name" placeholder="What for?">
    <input id="amt" type="number" placeholder="Amount (₹)">
  </div>
  <div class="row" style="margin-top:8px">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <input id="date" type="date">
    <button onclick="add()">Add</button>
  </div>
</div>
<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>
<div class="card"><b>All entries</b><div id="list"></div></div>
<script>
var items=[],budget=0;
try{items=JSON.parse(localStorage.getItem('exp')||'[]');budget=+localStorage.getItem('bud')||0}catch(e){}
var $=function(i){return document.getElementById(i)};
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN')}
function save(){try{localStorage.setItem('exp',JSON.stringify(items));localStorage.setItem('bud',budget)}catch(e){}}
$('date').valueAsDate=new Date();
$('budget').value=budget||'';
$('budget').oninput=function(){budget=+this.value||0;save();draw()};
function add(){
  var a=+$('amt').value;
  if(!a||a<=0){$('amt').focus();return}
  items.push({n:$('name').value.trim()||$('cat').value,a:a,c:$('cat').value,d:$('date').value});
  $('name').value='';$('amt').value='';save();draw();
}
function del(i){items.splice(i,1);save();draw()}
function draw(){
  var t=0,by={};
  items.forEach(function(x){t+=x.a;by[x.c]=(by[x.c]||0)+x.a});
  $('total').textContent=inr(t);
  var l=$('left');
  if(budget){var r=budget-t;l.className='muted'+(r<0?' over':'');l.textContent=r>=0?inr(r)+' left of '+inr(budget):inr(-r)+' over budget'}else l.textContent='';
  var h='';
  Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
    h+='<div style="display:flex;justify-content:space-between"><span>'+k+'</span><span>'+inr(by[k])+'</span></div><div class="track"><div class="bar" style="width:'+(by[k]/t*100)+'%"></div></div>';
  });
  $('cats').innerHTML=h||'<span class="muted">Nothing yet</span>';
  h='';
  items.map(function(x,i){return {x:x,i:i}}).sort(function(a,b){return (b.x.d||'')>(a.x.d||'')?1:-1}).forEach(function(o){
    h+='<div class="item"><div>'+esc(o.x.n)+'<div class="muted">'+o.x.c+' · '+(o.x.d||'')+'</div></div><div>'+inr(o.x.a)+'<button class="x" onclick="del('+o.i+')">✕</button></div></div>';
  });
  $('list').innerHTML=h||'<div class="muted">No entries yet</div>';
}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
draw();
</script></body></html>
```
